    ! * -> OverloadAllThermalBattery : if [PL > Ppv + Pw && PL - Ppv - Pw > eng3_Pmax + Pd1max + Pd2max];

    [*] -> PLZeroCharge;

    state PLZeroCharge {
        enter {
            Pgen_req = 0.0;
            Pbatt_discharge_req = 0.0;
            Pbatt_charge_req = Ppv + Pw;
            Pspare = 0.0;
            cutin_LNG = 0;
            cutin_DG1 = 0;
            cutin_DG2 = 0;
            cutout_LNG = 1;
            cutout_DG1 = 1;
            cutout_DG2 = 1;
